window.NOTES={"version":45,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子通信"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":44,"target":null,"chapter":2,"section":"2.1","topic":"程序与进程","title":"程序是静态代码，进程是一次运行实例","conclusion":"进程是程序在一定数据集上的一次执行过程，也是系统管理运行活动的重要抽象。","points":["同一程序可产生多个进程，每个进程有自己的运行状态和资源。","任务管理器可查看当前进程及CPU、内存占用。","结束一个进程不等于卸载程序；未保存的数据可能丢失。"],"boundary":"进程process不是泛指的处理processing，也不等同于磁盘上的可执行文件。","type":"填空","trigger":"从程序与进程的判断与应用整理。","id":"y2022q44","sources":[{"year":2022,"q":44,"type":"填空"}],"keys":["2022-44"],"related":[{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"在任务管理器中观察或结束一次运行实例，可具体理解进程与程序文件的区别。"},{"id":"y2024q33","label":"卸载程序不保证清除所有关联文件","reason":"结束进程只停止运行，卸载才移除软件主体；两类操作各自保留的内容不同。"}]},{"q":5,"chapter":2,"section":"2.1","type":"单选","topic":"操作系统特征","title":"并发、共享、虚拟和异步描述不同操作系统现象","trigger":"真题从多任务、资源共享、逻辑映射和事件发生次序考查操作系统特征。","conclusion":"多任务在一段时间内共同推进体现并发；共同使用资源体现共享；物理资源映射为逻辑资源体现虚拟；运行次序受调度影响体现异步。","points":["单核时间片也能实现并发，多核还可能实现真正并行。","共享资源需要互斥、同步和调度。","异步性意味着执行速度和先后受事件影响，不是完全预定的时间序列。","Windows可让多个任务在一段时间内共同推进；虚拟内存利用地址映射扩展可用的逻辑空间，但仍受地址空间、提交限制和可用存储等约束。"],"boundary":"并发不等于同一时刻并行；异步也不等于结果任意或系统没有确定规则。","id":"y2026q7","sources":[{"year":2023,"q":5,"type":"单选"},{"year":2026,"q":7,"type":"单选"},{"year":2021,"q":4,"type":"单选","page":2}],"keys":["2023-5","2026-7","2021-4"],"related":[{"id":"y2022q44","label":"程序是静态代码，进程是一次运行实例","reason":"并发调度作用于运行中的进程，先区分静态程序和运行实例。"},{"id":"y2025q1","label":"字长、主频、核心与指令速度是不同性能指标","reason":"单核时间片可并发，多核才可能同时并行；不能把核数直接相加成时钟频率。"},{"id":"y2025q7","label":"批处理系统的典型短板是交互性差","reason":"多道批处理让多个作业交替使用资源，是并发与共享的具体应用。"}]},{"q":6,"chapter":2,"section":"2.1","type":"单选","topic":"操作系统类型","title":"实时、分布式与通用操作系统按目标区分","trigger":"题目综合辨析操作系统安全、分布式系统、实时响应和后台服务。","conclusion":"操作系统负责资源管理、任务调度、接口与安全等多方面工作；实时系统强调在规定期限内响应，分布式系统协调多台计算机资源。","points":["安全不仅防止非法用户访问，还包括认证、授权、隔离、审计和完整性保护。","服务或后台进程可为系统与应用提供持续功能。","分布式操作系统试图把多台计算机的资源统一协调和呈现。"],"boundary":"“实时”强调可预测的时限，不只是平均速度快；操作系统安全也不能缩成单一访问限制。","id":"y2024q6","sources":[{"year":2024,"q":6,"type":"单选"}],"keys":["2024-6"],"related":[{"id":"merged-2","label":"系统软件与应用软件按功能区分","reason":"按资源管理与提供运行环境的功能判断，能说明操作系统为何属于系统软件。"},{"id":"y2026q7","label":"并发、共享、虚拟和异步描述不同操作系统现象","reason":"实时和分布式描述系统目标，并发、共享等描述运行现象，两组概念不能混用。"}]},{"q":6,"chapter":2,"section":"2.1","type":"单选","topic":"易用性","title":"提高易用性不靠增加系统复杂度","trigger":"题目要求找出操作系统为提高易用性通常不会采用的措施。","conclusion":"图形界面、帮助系统和多语言支持有利于易用性；无目的地增加复杂度会提高学习与操作成本。","points":["易用性强调容易学习、理解、操作和纠错。","功能丰富不等于界面复杂，良好设计会隐藏不必要的内部细节。","帮助、搜索、提示和一致的交互规则能降低认知负担。"],"boundary":"系统内部实现可能复杂，但不应把复杂度直接暴露给普通用户。","id":"y2025q6","sources":[{"year":2025,"q":6,"type":"单选"}],"keys":["2025-6"],"related":[{"id":"y2026q26","label":"任务栏承担启动、切换、状态与搜索","reason":"任务栏搜索与统一启动入口能减少寻找功能的步骤，是易用性的具体实现。"},{"id":"y2025q32","label":"“应用”保存设置但通常不关闭对话框","reason":"应用、确定、取消具有一致的操作反馈，有助于理解和纠错。"}]},{"q":7,"chapter":2,"section":"2.1","type":"单选","topic":"批处理系统","title":"批处理系统的典型短板是交互性差","trigger":"题目要求识别批处理操作系统的缺点。","conclusion":"批处理系统将作业成批提交并自动连续处理，吞吐量较高，但用户难以及时干预，交互性较差。","points":["批处理可减少人工装卸和处理器空闲时间。","多道批处理可让多个作业共同驻留内存并交替使用资源。","交互式任务更适合分时系统。"],"boundary":"批处理并非不能处理I/O，也不等于不支持多任务；应抓住“提交后等待结果”的交互特征。","id":"y2025q7","sources":[{"year":2025,"q":7,"type":"单选"}],"keys":["2025-7"],"related":[{"id":"y2026q7","label":"并发、共享、虚拟和异步描述不同操作系统现象","reason":"多道批处理中的作业交替推进体现并发，并不要求所有作业同一时刻执行。"},{"id":"y2024q6","label":"实时、分布式与通用操作系统按目标区分","reason":"选操作系统要先看目标：高吞吐、及时交互和规定期限内响应是不同需求。"}]},{"q":2,"chapter":2,"section":"2.2","type":"单选","topic":"窗口操作","title":"活动窗口、标题栏与窗口贴靠规则","trigger":"两道题从活动窗口和拖动标题栏考查Windows窗口状态与操作。","conclusion":"活动窗口是当前操作的顶层窗口，键盘输入送到它或其内部获得焦点的控件；置顶规定覆盖顺序，最小化、最大化和还原规定显示状态。","points":["单击可操作窗口通常将其激活；普通窗口被激活后通常移到其他普通窗口前方。","非活动的置顶窗口仍可能覆盖活动窗口，因此不能只看谁在前面判断键盘输入的去向。","最小化隐藏窗口的主要内容，程序通常仍在运行；最小化不等于结束进程。","支持最大化的窗口通常可双击标题栏，在最大化与还原之间切换。","启用贴靠时，拖到顶部通常最大化，拖到左右边缘可触发贴靠；拖到底部不是标准最小化手势。"],"boundary":"可见、活动、置顶和运行是不同状态；标题栏和贴靠操作还取决于窗口能力、Windows版本及设置。","id":"y2020q2","sources":[{"year":2020,"q":2,"type":"单选"},{"year":2025,"q":8,"type":"单选"}],"keys":["2020-2","2025-8"],"comparison":{"headers":["状态","主要含义","不能直接推出"],"rows":[["活动","当前操作的顶层窗口，其内部焦点控件可接收输入","一定覆盖所有置顶窗口"],["置顶","覆盖其他非置顶窗口","一定接收键盘输入"],["最小化","窗口主要内容暂时不在桌面展开","程序已经退出"],["最大化／还原","扩大窗口／回到此前大小和位置","增加／减少正在运行的程序数"]]},"related":[{"id":"y2022q44","label":"程序是静态代码，进程是一次运行实例","reason":"最小化改变窗口显示，进程通常继续运行，可用程序与进程区别排除误判。"},{"id":"y2022q34","label":"模式对话框阻塞父窗口，无模式对话框允许切回","reason":"窗口可见不代表可操作；模式对话框还会限制对父窗口的输入。"},{"id":"y2025q33","label":"粘贴和正常睡眠通常不会自动清空剪贴板","reason":"Alt＋Print Screen截取活动窗口，必须先判断键盘焦点与置顶显示的区别。"}],"pointGroups":[{"title":"活动、焦点与置顶的区别","indices":[0,1]},{"title":"最小化、最大化与贴靠操作","indices":[2,3,4]}]},{"q":34,"target":null,"chapter":2,"section":"2.2","topic":"对话框","title":"模式对话框阻塞父窗口，无模式对话框允许切回","conclusion":"模式对话框要求先完成或取消当前对话，再回到所属窗口；无模式对话框打开时仍能操作父窗口。","points":["另存为等要求确定目标的对话框通常是模式窗口。","查找等工具可作为无模式窗口，方便边查边编辑；具体行为以应用实现为准。","“应用”通常保存设置不关闭窗口，“确定”保存并关闭，“取消”放弃尚未应用的修改。"],"boundary":"模式性描述窗口交互范围，不是对话框是否能移动，也不意味着整个操作系统都无法使用。","type":"判断","trigger":"从对话框的判断与应用整理。","id":"y2022q34","sources":[{"year":2022,"q":34,"type":"判断"}],"keys":["2022-34"],"related":[{"id":"y2025q32","label":"“应用”保存设置但通常不关闭对话框","reason":"对话框是否阻塞父窗口与按钮是否保存、关闭是两条独立规则。"},{"id":"y2020q2","label":"活动窗口、标题栏与窗口贴靠规则","reason":"父窗口暂不能操作不等于整个系统失去活动窗口，可继续区分焦点和显示状态。"}]},{"q":32,"chapter":2,"section":"2.2","type":"判断","topic":"关机","title":"长按电源键是强制断电手段","trigger":"题目判断长按电源键能否作为正常关机方式。","conclusion":"长按电源键通常会强制关闭设备，应只在系统完全无响应且其他方法无效时使用。","points":["正常关机会让系统结束进程、写回缓存并关闭文件系统。","强制断电可能造成未保存数据丢失或文件系统损坏。","短按电源键的行为可在电源选项中配置。"],"boundary":"“可以把机器关掉”不等于“属于规范关机”。","id":"y2026q32","sources":[{"year":2026,"q":32,"type":"判断"}],"keys":["2026-32"],"related":[{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"应用失去响应时可先定位并结束相关进程，理解为何不应直接强制整机断电。"},{"id":"y2026q3","label":"RAM与ROM的断电特性","reason":"未保存内容常在易失性RAM中，强制断电会失去它并中断写回。"}]},{"q":3,"chapter":2,"section":"2.3","type":"单选","topic":"回收站","title":"Delete是否进入回收站取决于位置和方式","trigger":"两道判断题考查固定磁盘、移动介质和永久删除的不同结果。","conclusion":"本地可回收位置的普通Delete通常将文件移入回收站；Shift＋Delete、网络位置、部分移动介质及容量或策略设置可能使文件绕过回收站。","points":["回收站不是所有存储位置的统一保险箱，是否可回收要结合位置、删除方式和实际提示判断。","移入回收站的文件仍占用本机存储空间；清空回收站或从其中永久删除后，才释放相应文件占用的空间。","从回收站还原通常回到原文件夹；应核对原路径，避免只凭文件名判断恢复位置。","删除快捷方式与删除其目标文件是不同操作，应先确认选中的是哪个对象。","绕过或清空回收站后，不能再用该回收站的还原功能取回文件；其他备份或恢复工具能否恢复取决于具体条件。"],"boundary":"“永久删除”不等于已安全擦除全部数据，也不保证还能恢复；题干出现“一定”“所有”时，须检查介质、删除方式、容量和配置。","id":"y2020q3","sources":[{"year":2020,"q":3,"type":"单选"},{"year":2025,"q":35,"type":"判断"},{"year":2022,"q":45,"type":"填空"}],"keys":["2020-3","2025-35","2022-45"],"related":[{"id":"y2026q35","label":"快速访问汇集常用和固定位置","reason":"取消快速访问固定只移除入口；真正删除文件才适用回收站规则。"},{"id":"y2024q5","label":"磁盘清理用于移除可安全删除的系统临时内容","reason":"清空回收站能释放空间，但清理前应核对其中是否仍有需要恢复的文件。"},{"id":"y2026q33","label":"关闭系统保护会删除还原点并释放空间","reason":"回收站恢复与系统还原保护的对象不同，系统还原不能代替个人文件备份。"}],"pointGroups":[{"title":"回收位置、空间占用与还原","indices":[0,1,2]},{"title":"确认删除对象与恢复边界","indices":[3,4]}]},{"q":24,"chapter":2,"section":"2.3","type":"多选","topic":"文件操作","title":"复制、移动、拖放与批量重命名","trigger":"真题综合考查同盘/跨盘拖放默认规则、修饰键、剪贴板和多文件重命名。","conclusion":"资源管理器中，普通文件在同一卷的不同文件夹间左键拖动通常移动，跨卷通常复制；Ctrl、Shift、Alt及右键拖放菜单可明确请求动作。","points":["这里的“同盘／跨盘”主要按逻辑卷区分；一块物理硬盘上的C盘与D盘也属于跨卷。","Ctrl拖动通常复制，Shift拖动通常移动，Ctrl＋Shift或Alt拖动通常创建快捷方式；右键拖动可在松手后从菜单选择。","复制在目标建立副本并保留源文件；移动成功后文件离开原文件夹；快捷方式只建立指向目标的入口。","资源管理器剪切文件通常先标记待移动，粘贴成功后才完成移动；图标变淡不表示文件已经删除。","多文件可批量重命名，系统通常追加序号以区分名称；扩展名与实际格式仍须分别判断。","文件能否移动或删除还受访问权限、占用方式和是否允许共享删除等影响，并非所有打开的文件都绝对不能删除。"],"boundary":"默认拖放规则以可访问、可写的普通文件夹为前提；应用、压缩包和特殊系统对象可定义其他行为，应核对松手前的动作提示。","id":"y2020q24","sources":[{"year":2020,"q":24,"type":"多选"},{"year":2023,"q":43,"type":"填空"},{"year":2025,"q":27,"type":"多选"}],"keys":["2020-24","2023-43","2025-27"],"comparison":{"headers":["拖放条件","通常动作","源文件"],"rows":[["同卷普通拖动","移动","成功后离开原文件夹"],["跨卷普通拖动","复制","保留"],["Ctrl＋拖动","复制","保留"],["Shift＋拖动","移动","成功后离开原文件夹"],["Ctrl＋Shift＋拖动","创建快捷方式","保留"],["Alt＋拖动","创建快捷方式","保留"],["右键拖动后松手","从菜单选择动作","随所选动作变化"]]},"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"移动、删除和重命名还受完整文件名、属性及访问权限约束。"},{"id":"y2025q33","label":"粘贴和正常睡眠通常不会自动清空剪贴板","reason":"资源管理器剪切先标记待移动，成功粘贴才完成移动，与文本剪切的时机不同。"},{"id":"y2026q35","label":"快速访问汇集常用和固定位置","reason":"创建导航入口不复制或移动源文件，可与拖放创建快捷方式一起区分。"}],"pointGroups":[{"title":"先按逻辑卷和拖放提示判断动作","indices":[0,1,2]},{"title":"剪切文件何时完成移动","indices":[3]},{"title":"批量命名与操作权限","indices":[4,5]}]},{"q":34,"chapter":2,"section":"2.3","type":"填空","topic":"文件属性","title":"文件名、扩展名、关联、只读与权限要分层判断","trigger":"真题综合考查合法文件名、扩展名、默认打开程序，以及文件与文件夹只读属性的边界。","conclusion":"文件名、扩展名、默认打开程序、只读属性和访问权限分别约束名称、类型识别、打开方式及操作能力；不能把其中一项当成其他各项的替代。","points":["常规Windows文件名不能包含\\ / : * ? &quot; &lt; &gt; |；连字符和数字可以使用，名称也不应以空格或句点结尾。","CON、PRN、AUX、NUL、COM1至COM9、LPT1至LPT9等是保留设备名，NUL.txt等在保留名后加扩展名的形式也不能作为普通文件名。","扩展名通常参与类型识别和程序关联；显示或隐藏扩展名只改显示，更改默认应用只改打开关联，改扩展名不会转换内部格式。","my.txt与无扩展名的my是不同完整文件名，可在同一文件夹共存；隐藏扩展名可能让它们看起来同名，但不改变实际名称。","只读文件会限制普通写入；直接删除接口也可能因只读而失败，工具可能先处理属性再删除。文件夹只读标记不等于禁止创建子项，创建能力主要取决于目录访问权限。","常见属性还有隐藏、存档等；隐藏不提供保密或访问保护。能否删除还要检查权限及文件打开方式是否允许共享删除。"],"boundary":"没有九个禁用字符不等于名称一定合法；基础题可按规范扩展名判断类型，实际格式须结合内容。只读、隐藏都不能替代NTFS等访问权限，也不能提供可靠防误删保证。","id":"merged-4","sources":[{"year":2020,"q":34,"type":"填空"},{"year":2023,"q":24,"type":"多选"},{"year":2023,"q":33,"type":"判断"},{"year":2023,"q":34,"type":"判断"},{"year":2026,"q":24,"type":"多选"},{"year":2022,"q":9,"type":"单选"},{"year":2021,"q":24,"type":"多选","page":4}],"keys":["2020-34","2023-24","2023-33","2023-34","2026-24","2022-9","2021-24"],"related":[{"id":"y2020q24","label":"复制、移动、拖放与批量重命名","reason":"批量重命名不转换文件格式，移动或删除也要检查权限和占用方式。"},{"id":"y2022q75","label":"Windows 10可用“发送到→压缩(zipped)文件夹”","reason":"把扩展名改成.zip不能产生压缩包，是名称与实际格式分离的直接例子。"},{"id":"y2026q9","label":"移动存储策略可分别限制读写权限","reason":"只读属性与策略中的拒绝写入不是同一层控制，读取和写入限制还需分别判断。"}],"pointGroups":[{"title":"完整文件名是否合法","indices":[0,1,3]},{"title":"扩展名、关联与真实格式","indices":[2]},{"title":"属性与访问权限能限制什么","indices":[4,5]}]},{"q":75,"target":null,"chapter":2,"section":"2.3","topic":"压缩文件夹","title":"Windows 10可用“发送到→压缩(zipped)文件夹”","conclusion":"选择文件夹，右击后选择“发送到→压缩(zipped)文件夹”，系统创建一个ZIP副本，原文件夹仍保留。","points":["ZIP存储文件内容和目录结构；是否明显变小取决于原数据的可压缩性。","JPEG、MP4等已压缩内容再次ZIP通常节省不多。","“添加到压缩文件”常由第三方压缩软件添加，不能假定每台Windows都有此菜单。"],"boundary":"把扩展名改为.zip只改名字，不生成合法压缩包，也不会压缩内容。","type":"综合","trigger":"从压缩文件夹的判断与应用整理。","id":"y2022q75","sources":[{"year":2022,"q":75,"type":"综合"}],"keys":["2022-75"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"扩展名只参与类型识别，生成ZIP必须实际压缩，不能只改文件名。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"JPEG、MP3等已有压缩的内容再打包通常缩小有限，要先理解有损与无损压缩。"}]},{"q":25,"chapter":2,"section":"2.3","type":"多选","topic":"桌面图标","title":"“此电脑”图标可通过个性化设置恢复","trigger":"题目要求识别把“此电脑”重新显示到桌面的有效入口。","conclusion":"可在设置或个性化的“桌面图标设置”中勾选“计算机”，也可通过系统提供的相关入口进入该设置。","points":["“此电脑”是系统桌面图标，不等同于普通快捷方式。","不同Windows 10版本的设置入口文字可能略有差异。","恢复图标不会改变磁盘内容，只改变桌面显示。","也可从资源管理器把“此电脑”拖到桌面创建快捷方式，或通过发送到→桌面快捷方式创建普通项目入口；快捷方式与“桌面图标设置”恢复的系统图标要区分。"],"boundary":"在桌面新建同名文件夹不能替代系统的“此电脑”入口。","version":"按Windows 10常见界面整理","id":"y2026q25","sources":[{"year":2026,"q":25,"type":"多选"}],"keys":["2026-25"],"related":[{"id":"y2026q35","label":"快速访问汇集常用和固定位置","reason":"桌面图标和快速访问都提供导航入口，恢复或固定入口不改变目标数据。"},{"id":"y2020q24","label":"复制、移动、拖放与批量重命名","reason":"拖到桌面创建快捷方式时应核对拖放动作，避免误把入口创建当成文件移动。"}]},{"q":35,"chapter":2,"section":"2.3","type":"判断","topic":"快速访问","title":"快速访问汇集常用和固定位置","trigger":"题目判断文件资源管理器中的快速访问是否方便进入常用文件夹。","conclusion":"快速访问汇集固定文件夹和常用位置，方便导航；“从快速访问取消固定”只移除固定入口，原文件夹及其内容仍在原处。","points":["可右击文件夹并选择“固定到快速访问”，让其成为方便进入的导航入口。","固定不会移动或复制原文件夹；不再需要该入口时，可执行“从快速访问取消固定”。","常用文件夹和最近文件是否显示，可在文件资源管理器选项中配置。","在文件列表里针对实际文件或文件夹执行“删除”，仍应按普通文件删除规则判断。"],"boundary":"不要把“取消固定”“从列表移除”和“删除文件”统称为删除入口；原文件是否保留取决于执行的具体命令。","id":"y2026q35","sources":[{"year":2026,"q":35,"type":"判断"}],"keys":["2026-35"],"related":[{"id":"y2020q3","label":"Delete是否进入回收站取决于位置和方式","reason":"取消固定不进入回收站；只有针对实际文件执行删除才判断回收位置和方式。"},{"id":"y2026q25","label":"“此电脑”图标可通过个性化设置恢复","reason":"系统桌面图标、普通快捷方式和固定位置都是不同入口类型，不能用同名文件夹替代。"}]},{"q":23,"chapter":2,"section":"2.4","type":"多选","topic":"控制面板与账户","title":"控制面板视图与管理员账户的权限边界","trigger":"真题从控制面板任务、显示方式和用户账户类型考查Windows经典设置入口。","conclusion":"控制面板可管理账户、程序、外观和防火墙等设置；管理员账户可在确认提升后执行影响全系统或其他用户的管理操作。","points":["控制面板可按类别、大图标或小图标显示。","标准账户适合日常使用，管理员凭据用于安装、配置和账户管理。","Windows 10部分经典入口会跳转到“设置”应用。","账户显示名称可以按账户类型和权限修改；管理内置Administrator与普通管理员账户不是一回事。Windows 10日常权限判断以标准账户、管理员及UAC提升为主。","控制面板是经典系统设置入口；Windows 10部分选项已迁入“设置”，不能把旧表述“所有设置都在控制面板”照搬。"],"boundary":"管理员不表示所有程序始终以最高权限运行；控制面板也不能替代任务管理器管理每个进程。","id":"y2025q26","sources":[{"year":2023,"q":23,"type":"多选"},{"year":2023,"q":44,"type":"填空"},{"year":2025,"q":26,"type":"多选"},{"year":2021,"q":5,"type":"单选","page":2},{"year":2021,"q":34,"type":"填空","page":6}],"keys":["2023-23","2023-44","2025-26","2021-5","2021-34"],"related":[{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"控制面板管理系统设置，任务管理器管理运行活动，遇到进程问题应选对入口。"},{"id":"y2026q9","label":"移动存储策略可分别限制读写权限","reason":"可移动存储的读写策略需要授权管理，管理员身份仍要结合提升与版本能力。"}],"pointGroups":[{"title":"控制面板视图与设置入口","indices":[0,2,4]},{"title":"账户身份与管理权限","indices":[1,3]}]},{"q":24,"chapter":2,"section":"2.4","type":"多选","topic":"任务管理与远程边界","title":"任务管理器管理当前主机的进程、性能和启动项","trigger":"真题从结束应用、查看资源、远程桌面边界与常用命令考查任务管理器。","conclusion":"任务管理器直接管理当前会话所在系统，可查看或结束进程、查看性能、管理启动项；远程桌面连接后管理的是远程主机。","points":["结束任务只终止当前进程，不卸载软件。","性能页显示CPU、内存、磁盘和网络资源。","远程连接必须满足网络、系统设置、认证和授权条件。","任务管理器可查看进程对应文件的属性、打开文件所在位置，并在“启动”页管理开机启动项；结束进程不等于卸载程序或删除文件。"],"boundary":"任务管理器不是完整卸载器，也不是绕过权限的远程监控平台。","id":"y2026q34","sources":[{"year":2024,"q":24,"type":"多选"},{"year":2024,"q":34,"type":"判断"},{"year":2025,"q":28,"type":"多选"},{"year":2026,"q":34,"type":"判断"}],"keys":["2024-24","2024-34","2025-28","2026-34"],"related":[{"id":"y2022q44","label":"程序是静态代码，进程是一次运行实例","reason":"任务管理器列出运行实例，因此结束任务不等于删除磁盘上的程序文件。"},{"id":"y2024q33","label":"卸载程序不保证清除所有关联文件","reason":"需要移除软件主体时应卸载，不能以结束进程替代。"},{"id":"y2026q8","label":"设备管理器查看硬件与驱动状态","reason":"进程异常与硬件驱动异常使用不同管理工具，先按问题对象选择入口。"}]},{"q":44,"chapter":2,"section":"2.4","type":"填空","topic":"任务栏与搜索","title":"任务栏承担启动、切换、状态与搜索","trigger":"真题从任务栏组成、开始菜单搜索和搜索范围考查Windows桌面入口。","conclusion":"任务栏集中提供开始菜单、应用启动与切换、搜索、任务视图和系统状态；搜索可定位应用、设置和建立索引的本地文件。","points":["搜索框可隐藏或仅显示图标，也可直接在开始菜单输入。","搜索结果受索引、权限、版本和网络配置影响。","通知区域显示网络、音量、时间等状态。","Windows 10任务栏右键菜单可打开任务管理器、设置任务栏；任务栏最右端可显示桌面。应用自身的功能设置仍要进入应用。","Windows 10搜索可涉及本地文件、应用、设置及网络结果；具体网络结果受配置和连接影响，不能说搜索只能用于本地。","桌面右键→个性化→背景，可选择纯色、图片或幻灯片放映；背景设置不属于任务栏右键菜单的直接功能。"],"boundary":"没有搜到不等于文件不存在；桌面背景设置也不属于任务栏功能。","id":"y2026q26","sources":[{"year":2024,"q":44,"type":"填空"},{"year":2025,"q":9,"type":"单选"},{"year":2026,"q":26,"type":"多选"},{"year":2022,"q":7,"type":"单选"}],"keys":["2024-44","2025-9","2026-26","2022-7"],"related":[{"id":"y2020q2","label":"活动窗口、标题栏与窗口贴靠规则","reason":"任务栏切换应用后仍需区分窗口是否活动、最小化以及进程是否运行。"},{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"任务栏可提供任务管理器入口，进一步查看当前进程与资源占用。"},{"id":"y2026q25","label":"“此电脑”图标可通过个性化设置恢复","reason":"桌面系统图标与背景设置属于个性化范围，不能把所有桌面相关操作都归入任务栏。"}],"pointGroups":[{"title":"搜索入口及结果范围","indices":[0,1,4]},{"title":"任务栏状态和管理入口","indices":[2,3]},{"title":"桌面背景应在哪里设置","indices":[5]}]},{"q":45,"chapter":2,"section":"2.4","type":"填空","topic":"设备管理器","title":"设备管理器查看硬件与驱动状态","trigger":"真题从工具名称和异常图标考查硬件设备管理。","conclusion":"设备管理器列出硬件类别和状态，可查看驱动、启用或禁用设备、扫描硬件改动；黄色感叹号提示需要进一步诊断。","points":["应打开属性读取设备状态和错误代码。","更新驱动前先确认型号、系统版本和来源。","磁盘分区主要由磁盘管理工具负责。"],"boundary":"异常图标是线索，不是最终原因；设备消失也可能来自连接或硬件问题。","id":"y2026q8","sources":[{"year":2024,"q":45,"type":"填空"},{"year":2026,"q":8,"type":"单选"}],"keys":["2024-45","2026-8"],"related":[{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"硬件及驱动状态由设备管理器处理，CPU占用与进程结束则看任务管理器。"}]},{"q":32,"chapter":2,"section":"2.4","type":"判断","topic":"对话框按钮","title":"“应用”保存设置但通常不关闭对话框","trigger":"题目判断Windows对话框中单击“应用”后的结果。","conclusion":"“应用”通常让修改立即生效并保留对话框，“确定”通常应用修改并关闭对话框。","points":["“取消”通常关闭并放弃尚未应用的修改。","已单击“应用”的修改不一定能再由“取消”撤销。","按钮行为仍以具体程序实际设计为准。"],"boundary":"不要把“应用”和“确定”的共同点背成完全相同；关键差异是是否关闭窗口。","id":"y2025q32","sources":[{"year":2025,"q":32,"type":"判断"}],"keys":["2025-32"],"related":[{"id":"y2022q34","label":"模式对话框阻塞父窗口，无模式对话框允许切回","reason":"应用或确定描述按钮行为，模式或无模式描述父窗口能否继续操作，应分开判断。"}]},{"q":9,"chapter":2,"section":"2.4","type":"单选","topic":"组策略","title":"移动存储策略可分别限制读写权限","trigger":"题目考查本地组策略中对USB等可移动存储设备的访问控制。","conclusion":"Windows策略可以分别配置可移动磁盘的读取、写入和执行权限。","points":["拒绝写入可防止向设备复制数据，但仍可能允许读取。","拒绝读取会阻止访问设备内容，通常也使正常使用受到更大限制。","策略修改应由授权管理员进行，并考虑组织安全规范。"],"boundary":"策略名称和可用项会随Windows版本与版本类型变化，家庭版通常不提供完整本地组策略编辑器。","id":"y2026q9","sources":[{"year":2026,"q":9,"type":"单选"}],"keys":["2026-9"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"拒绝写入的策略与文件只读属性、目录权限分别生效，不能用隐藏属性代替访问保护。"},{"id":"y2025q26","label":"控制面板视图与管理员账户的权限边界","reason":"修改影响系统的存储策略前要确认授权和管理员提升，账户名称本身不保证最高权限。"}]},{"q":4,"chapter":2,"section":"2.5","type":"单选","topic":"剪贴板","title":"粘贴和正常睡眠通常不会自动清空剪贴板","trigger":"真题从重复粘贴与睡眠唤醒两个场景考查剪贴板内容的保留。","conclusion":"文本、图片等内容粘贴后通常仍可继续粘贴，正常睡眠与唤醒也不必然清空剪贴板；资源管理器的文件剪切移动及剪贴板历史须分别判断。","points":["复制或剪切通常更新当前剪贴板内容；Ctrl＋V粘贴当前内容，普通粘贴本身通常不会将文本或图片内容用完。","文本剪切通常立即移除选中文字；资源管理器剪切文件通常只标记待移动，粘贴成功后才完成位置变化。","复制文件时，剪贴板可记录文件位置与传输信息，不能把它当成整个文件已经完整备份到内存。","开启Windows剪贴板历史后，可用Win＋V选择较早项目；Windows历史与Office剪贴板是不同功能。","正常睡眠通常保留当前会话，但不能与关机或重启混为一谈；重启会清除未固定的Windows历史项目，固定项目可保留。","传统Windows截图按键中，Print Screen复制全屏，Alt＋Print Screen复制活动窗口，结果进入剪贴板；重新配置按键行为时按实际设置执行。"],"boundary":"文件剪切移动完成后，不能据“文本可重复粘贴”推断必能再次粘贴出文件副本；Windows历史有格式、大小和数量限制，不能保存任意文件。策略、程序行为和手动清除也可能影响内容。","id":"y2025q33","sources":[{"year":2023,"q":4,"type":"单选"},{"year":2025,"q":33,"type":"判断"}],"keys":["2023-4","2025-33"],"comparison":{"headers":["场景","剪切或复制后","粘贴或重启后"],"rows":[["文本剪切","所选文字通常立即离开源位置","粘贴后通常仍可继续粘贴"],["文件剪切","源文件通常仍在，只被标记待移动","粘贴成功后才完成移动，不按重复复制理解"],["文件复制","源文件保留，剪贴板提供文件传输信息","目标建立副本，仍依赖源文件可访问"],["Windows剪贴板历史","开启后可保留支持的较早项目","重启清除未固定项目，固定项目可保留"]]},"related":[{"id":"y2020q24","label":"复制、移动、拖放与批量重命名","reason":"文件剪切粘贴是位置移动，不能照搬文本可重复粘贴的结论。"},{"id":"y2026q3","label":"RAM与ROM的断电特性","reason":"普通剪贴板与RAM暂存有关，固定历史等额外功能不能一概按断电丢失处理。"},{"id":"y2025q34","label":"Windows附件各有功能边界","reason":"粘贴是否保留表格与图片还取决于目标应用，纯文本记事本不会保留Word丰富结构。"}],"pointGroups":[{"title":"复制、剪切与粘贴何时改变内容","indices":[0,1,2]},{"title":"剪贴板历史与睡眠、重启","indices":[3,4]},{"title":"截图怎样进入剪贴板","indices":[5]}]},{"q":5,"chapter":2,"section":"2.5","type":"单选","topic":"磁盘清理","title":"磁盘清理用于移除可安全删除的系统临时内容","trigger":"题目要求选择用于清理临时文件、回收站内容和系统残留的Windows工具。","conclusion":"Windows的磁盘清理或“存储/临时文件”功能可扫描并删除选定的临时内容，释放磁盘空间。","points":["清理前应阅读分类说明，确认下载、回收站等位置是否仍有需要的文件。","卸载应用与清理临时文件是两类操作。","磁盘碎片整理不会替代临时文件清理，SSD也不需要传统机械式碎片整理。"],"boundary":"清理工具不是备份工具；删除“以前的Windows安装”等项目后，相关回退能力可能消失。","id":"y2024q5","sources":[{"year":2024,"q":5,"type":"单选"}],"keys":["2024-5"],"related":[{"id":"y2020q3","label":"Delete是否进入回收站取决于位置和方式","reason":"清空回收站才释放被回收文件的空间，也会失去该回收站的直接还原能力。"},{"id":"y2024q33","label":"卸载程序不保证清除所有关联文件","reason":"卸载软件与清理临时文件删除的对象不同，不能把用户文档当作卸载残留清除。"},{"id":"y2026q33","label":"关闭系统保护会删除还原点并释放空间","reason":"还原点也占空间，但删除它们会降低恢复能力，应与普通临时内容分开判断。"}]},{"q":33,"chapter":2,"section":"2.5","type":"判断","topic":"软件卸载","title":"卸载程序不保证清除所有关联文件","trigger":"题目判断从Windows卸载应用后是否一定删除所有文件和设置。","conclusion":"卸载通常移除程序主体和注册信息，但可能保留用户文档、配置、缓存、日志或共享组件。","points":["保留配置可方便以后重装恢复偏好。","用户创建的数据通常不应被卸载器擅自删除。","需要彻底清理时应先备份，再按软件官方说明检查残留。"],"boundary":"残留不一定是故障或垃圾；共享组件和用户数据不能仅凭目录名称直接删除。","id":"y2024q33","sources":[{"year":2024,"q":33,"type":"判断"}],"keys":["2024-33"],"related":[{"id":"y2022q44","label":"程序是静态代码，进程是一次运行实例","reason":"停止一次运行只结束进程；卸载涉及程序主体，两者都不等于自动删除用户数据。"},{"id":"y2024q5","label":"磁盘清理用于移除可安全删除的系统临时内容","reason":"程序残留与可安全清理的临时内容要先分类核对，不能只按文件夹名称批量删除。"}]},{"q":33,"chapter":2,"section":"2.5","type":"判断","topic":"系统还原","title":"关闭系统保护会删除还原点并释放空间","trigger":"题目判断禁用系统还原是否能释放磁盘空间。","conclusion":"关闭某驱动器的系统保护并删除已有还原点可以释放其占用空间。","points":["还原点保存系统文件、注册表和部分配置快照。","系统还原不是个人文件备份。","更稳妥的做法是调整最大使用量或清理旧还原点，而非长期关闭保护。"],"boundary":"释放空间会牺牲恢复能力，操作前应确保有其他可靠备份。","id":"y2026q33","sources":[{"year":2026,"q":33,"type":"判断"}],"keys":["2026-33"],"related":[{"id":"y2024q5","label":"磁盘清理用于移除可安全删除的系统临时内容","reason":"释放磁盘空间时可比较临时内容和还原点；后者还承担系统恢复用途。"},{"id":"y2020q3","label":"Delete是否进入回收站取决于位置和方式","reason":"系统还原不替代回收站还原或文件备份，三者保护的对象和条件不同。"}]},{"q":25,"chapter":2,"section":"2.6","type":"多选","topic":"Windows实用工具","title":"Windows附件各有功能边界","trigger":"真题从截图、记事本、计算器、画图和水印处理考查系统工具。","conclusion":"记事本处理纯文本，计算器可做日期等计算，画图可转换常见图像格式；截图工具不会自动去除内容中的水印。","points":["截图工具可支持多种保存格式，具体取决于版本。","画图“另存为”可改变格式，但有损格式可能降低质量。","去水印涉及图像编辑、授权和内容真实性，不能视为截图的默认功能。","记事本保存纯文本，粘贴Word表格或网页内容时不会保留原表格结构、图片和丰富格式。字体设置主要改变显示方式，不保存逐字字体格式。","本章以Windows 10传统记事本为准：保存纯文本，不保存逐字颜色、表格边框等富文本格式。"],"boundary":"系统工具会随Windows更新，记忆时应抓住长期稳定的任务边界。","id":"y2025q34","sources":[{"year":2024,"q":25,"type":"多选"},{"year":2025,"q":34,"type":"判断"},{"year":2022,"q":8,"type":"单选"}],"keys":["2024-25","2025-34","2022-8"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"图像格式转换需要画图另存为等实际处理，修改扩展名本身不能完成转换。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"画图另存为JPEG等格式时可能丢失细节，需结合有损与无损压缩判断结果。"},{"id":"y2025q33","label":"粘贴和正常睡眠通常不会自动清空剪贴板","reason":"截图结果可能先进入剪贴板，粘贴后的结构是否保留还取决于接收应用。"}],"pointGroups":[{"title":"截图、画图与图像格式","indices":[0,1,2]},{"title":"记事本只保留哪些内容","indices":[3,4]}]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
